//! The committed `tests/fixtures/ours-v2/lifecycle.*`, which keripy accepts in
//! full (`verify_ours.py` there), still resolves, and this crate still reads
//! what it recorded.
//!
//! The fixture is regenerated by `examples/emit_keripy_fixture.rs` and checked
//! with keripy by hand; see `verify_ours.py`. Without keripy, this keeps the
//! two from drifting apart.

use affinidi_did_webs::{DidWebs, Kels, resolve_from_artifacts};
use serde_json::Value;

fn fixture(name: &str) -> Vec<u8> {
    std::fs::read(
        std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests/fixtures/ours-v2")
            .join(name),
    )
    .unwrap()
}

#[test]
fn the_lifecycle_keripy_accepts_resolves() {
    let spec: Value = serde_json::from_slice(&fixture("lifecycle.json")).unwrap();
    let keri_cesr = fixture("lifecycle.keri.cesr");
    let did_json = fixture("lifecycle.did.json");
    let did = DidWebs::parse(spec["did"].as_str().unwrap()).unwrap();

    let state = Kels::parse(&keri_cesr)
        .unwrap()
        .key_state(did.aid())
        .unwrap();
    assert_eq!(state.sn, spec["kel"]["sn"].as_u64().unwrap());
    assert_eq!(
        state.last_event_digest,
        spec["kel"]["said"].as_str().unwrap()
    );

    let doc = resolve_from_artifacts(&did, &keri_cesr, Some(&did_json)).expect("resolves");
    let doc = serde_json::to_value(doc).unwrap();
    // The new key agreement key only, the designated service, and the
    // endpoint endorsed under the rotation.
    assert_eq!(doc["keyAgreement"].as_array().unwrap().len(), 1, "{doc}");
    let services = doc["service"].to_string();
    assert!(services.contains("DIDCommMessaging"), "{services}");
    assert!(services.contains("https://example.com/v2/"), "{services}");
    let issued = spec["credentials"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|c| c["expect"] == "issued")
        .count();
    assert_eq!(issued, 3, "aliases, the new key agreement, the service");
}
